styles.css:
@keyframes kenburns { 
  0% { transform: scale(1) translate(0px, 0px); }
  100% { transform: scale(1.18) translate(-2.5%, -2%); }
}

@keyframes lw-pulse { 
  0% { box-shadow: rgba(0, 184, 148, 0.6) 0px 0px 0px 0px; }
  70% { box-shadow: rgba(0, 184, 148, 0) 0px 0px 0px 8px; }
  100% { box-shadow: rgba(0, 184, 148, 0) 0px 0px 0px 0px; }
}

@keyframes af-kenburns { 
  0% { transform: scale(1) translate(0px, 0px); }
  100% { transform: scale(1.08) translate(-1.5%, -1%); }
}

@keyframes doomPulse { 
  0%, 100% { transform: scale(1); text-shadow: rgba(255, 107, 107, 0) 0px 0px 0px; }
  50% { transform: scale(1.08); text-shadow: rgba(255, 107, 107, 0.85) 0px 0px 14px; }
}

@keyframes sp-drift { 
  0% { transform: scale(1) translate(0px, 0px); }
  100% { transform: scale(1.06) translate(-1.5%, -1%); }
}

@keyframes sp-bob { 
  0% { transform: translate(0px, 0px); }
  50% { transform: translate(6px, -8px); }
  100% { transform: translate(-5px, 6px); }
}

@keyframes sp-lb-in { 
  0% { opacity: 0; transform: translateY(-14px); }
  100% { opacity: 1; transform: none; }
}

